// 构建脚本：用 esbuild 打包 Web 客户端侧。
// React / react-dom / jsx-runtime 保持 EXTERNAL —— DSH 客户端模块加载器
// 从宿主图中解析它们（dsh-client-modules 的 `require(spec)` 遍历）。
// 我们自己的纯核心模块被 INLINE，使浏览器运行的投影/R1–R7 逻辑与宿主测试
// 覆盖的完全一致（两侧之间无逻辑漂移）。

import { build } from "esbuild";
import { fileURLToPath } from "node:url";
import { dirname, join } from "node:path";

const root = dirname(dirname(fileURLToPath(import.meta.url)));

const HEADER = `// Generated by scripts/build-client.mjs — do not edit.
// @generated model-assistant web client
`;

const banner = `${HEADER}window.__ModuleLoader__.load({
	id: "dsh-model-assistant",
	factory: (require) => {
		var module = { exports: {} };
		var exports = module.exports;
`;

const footer = `
		return module.exports;
	}
});
`;

await build({
  entryPoints: [join(root, "src", "client", "index.jsx")],
  bundle: true,
  // 用 cjs，esbuild 才能产出 `module.exports = __toCommonJS(...)` —— 下面的
  // factory 必须 RETURN 那个对象；iife 会让 module.exports 为空。
  format: "cjs",
  platform: "browser",
  target: ["es2022"],
  external: ["react", "react-dom", "react/jsx-runtime", "react-dom/client"],
  jsx: "automatic",
  outfile: join(root, "lib", "client.js"),
  banner: { js: banner },
  footer: { js: footer },
  legalComments: "none",
  minify: false,
  logLevel: "info",
});

console.log("已构建 lib/client.js");
